#!/usr/bin/env node
/* Builds dist/: a pack folder whose single runtime entry contains everything (prng.js + runtime.js + bind.js), because the
 * paperdolls build inlines only runtime.entry.   node packs/great-retrofit/tools/bundle.js
 * Then: paperdolls pack build packs/great-retrofit/dist --out retrofit.html [--scene jette.json]
 * dist/ is generated and not committed.
 */
'use strict';
const fs = require('fs'), path = require('path');
const pack = path.join(__dirname, '..'), dist = path.join(pack, 'dist');
fs.mkdirSync(dist, { recursive: true });
const read = p => fs.readFileSync(p, 'utf8');
const parts = [path.join(pack, '..', '..', 'v3', 'js', 'prng.js'), path.join(pack, 'runtime.js'), path.join(pack, 'bind.js')];
const out = '/* great-retrofit bundle: v3/js/prng.js + runtime.js + bind.js (generated by tools/bundle.js; edit the sources) */\n' + parts.map(read).join('\n;\n');
if (out.includes('</script>')) throw new Error('bundle contains </script>');
fs.writeFileSync(path.join(dist, 'runtime.bundle.js'), out);
fs.writeFileSync(path.join(dist, 'pack.yaml'), read(path.join(pack, 'pack.yaml')).replace(/entry: runtime\.js/, 'entry: runtime.bundle.js'));
console.log('wrote ' + path.relative(process.cwd(), dist));
